@testitem "matches sort on random vectors" begin
    using Random
    rng = MersenneTwister(5)
    for _ in 1:2000
        v = rand(rng, -5:5, rand(rng, 1:15))   # many duplicates on purpose
        k = rand(rng, 1:length(v))
