@testitem "random strings agree with the oracle and are valid UTF-8" begin
    using Random
    # Oracle: longest k such that every string starts with the first k characters
    # of the first string. Uses `first` and `startswith`, no code-unit access.
    function oracle(strs)
        isempty(strs) && return ""
        s1 = first(strs)
        for k in length(s1):-1:0
            p = first(s1, k)
            all(s -> startswith(s, p), strs) && return p
        end
    end
    rng = MersenneTwister(7)
    alphabet = ['a', 'ñ', 'ò', '€', '日']
    for _ in 1:2000
        strs = String[String(rand(rng, alphabet, rand(rng, 0:5))) for _ in 1:rand(rng, 0:4)]
        r = common_prefix(strs)
        @test isvalid(r)
        @test r == oracle(strs)
    end
end

