@testitem "random short strings agree with the naive recursion" begin
    using Random
    # Oracle: the textbook recursive definition on Vector{Char}, no table.
    function naive(x, y)
        isempty(x) && return length(y)
        isempty(y) && return length(x)
        return min(naive(x[2:end], y) + 1, naive(x, y[2:end]) + 1,
                   naive(x[2:end], y[2:end]) + (x[1] == y[1] ? 0 : 1))
    end
    rng = MersenneTwister(8)
    alphabet = ['a', 'b', 'ñ', 'é', '日']
    for _ in 1:300
        a = String(rand(rng, alphabet, rand(rng, 0:5)))
        b = String(rand(rng, alphabet, rand(rng, 0:5)))
        @test edit_distance(a, b) == naive(collect(a), collect(b))
    end
end

