@testitem "random lists agree with concatenate-and-sort" begin
    using Random
    rng = MersenneTwister(4)
    for _ in 1:1000
        lists = [sort(rand(rng, 0:9, rand(rng, 0:6))) for _ in 1:rand(rng, 0:5)]
        # Oracle: concatenate and sort.
        @test merge_sorted(lists) == sort(reduce(vcat, lists; init = Int[]))
    end
end

